import random
random.seed(1)

def beats(a, b):
    w = 0
    for x in a:
        for y in b:
            if x > y: w += 1
    return w

def score(dice):
    s = 0
    for i in range(5):
        w = beats(dice[i], dice[(i+1)%5])
        s += max(0, 19 - w)
    return s

best_found = None
for restart in range(500):
    dice = [sorted(random.choices(range(12), k=6)) for _ in range(5)]
    cur_s = score(dice)
    for step in range(20000):
        if cur_s == 0:
            break
        i = random.randrange(5)
        j = random.randrange(6)
        old_die = list(dice[i])
        new_val = random.randrange(12)
        new_die = sorted(old_die[:j] + old_die[j+1:] + [new_val])
        dice[i] = new_die
        new_s = score(dice)
        if new_s <= cur_s:
            cur_s = new_s
        else:
            dice[i] = old_die
    if cur_s == 0:
        print("found on restart", restart, dice)
        for i in range(5):
            print(beats(dice[i], dice[(i+1)%5]))
        best_found = dice
        break

print("done", best_found)

